#pragma once	typedef long mediTAG;	typedef long meliTAG;	typedef long sounTAG;	typedef long stliTAG;	typedef long dot256TAG;	typedef long partTAG;	typedef long amsoTAG;	typedef long meshTAG;	typedef long windTAG;	struct meshHeader	{		char plugName[32];			// Plug-in header (me)		long type;					// mesh .256 etc.		long name;		long plugHeaderQ1;		long plugHeaderQ2;		long plugHeaderOffset;		long plugLength;		long plugHeaderQ4;		long plugHeaderQ5;		dot256TAG dot256TagID;		// ID code for the .256 tag used for									// this map. (thanks Thanquol!)		mediTAG waterType1;			// ID used to represent water		short meshWidth;			// Number of columns in the mesh [1]		short meshHeight;			// Number of rows in the mesh [1]		long unknown1;				// Usually zeros		long meshLength;			// Total length of the grid data in bytes		long unknown2;				// Usually zeros		long meshOffset;			// Offset from beginning of tag to the									// start of the height mesh data		long tagLength;				// Total length of data from tag start		long unknown3;				// Usually zeros		long itemTypeCount;			// Number of item types used on map [2]		long itemTypeOffset;		// Offset from start of height mesh data		long itemTypeLength;		// Total length of the item type data		long unknown4;				// Usually zeros		long itemCount;				// Number of individual items used		long itemOffset;			// Offset from start of height mesh data		long itemLength;			// Total length of the item data		long unknown5;				// Usually zeros		meliTAG lighting;			// Lighting for the level		mediTAG waterType2;			// Second ID used to represent water		short netFlag;				// Single/multiplayer flags [3]		short flags2;				// Types of games playable on map [4]		partTAG particleEffect;		// Rain and snow		long maxTeams;				// Maximum number of teams on map		long unknown6; 				// Usually zeros		long unknown7;				// Usually zeros		long unknown8;				// Usually zeros		long unknown9;				// Usually zeros		long unknown10;				// Usually zeros		long unknown11;				// Usually zeros		long unknown12;				// Usually zeros		short unknown13;			// No idea		short unknown14;			// No idea		short unknown15;			// No idea		short unknown16;			// No idea		amsoTAG ambientSound;		// Global ambient sound ID		long actionCount;			// Number of scripted actions on level		long actionOffset;			// Offset from start of height mesh data		long actionLength;			// Total length of the action data		stliTAG nameID;				// Name of the map (stli tag reference)		dot256TAG postScreen;		// Post-level screen ID (.256 tag)		dot256TAG preScreen;		// Pre-level screen ID (.256 tag)		dot256TAG overheadMap;		// Overhead map ID (.256 tag)		meshTAG nextLevel;			// Next level ID (mesh tag)		long unknown17;				// No idea		long objectives;			// In-level objectives and subtitles		long unknown18;				// No idea		long unknown19;				// No idea		long narrationText;			// Scrolling text seen pre-level		long unknown20;				// No idea		long unknown21;				// No idea		long unknown22;				// No idea		long waterMaskOffset;				// Offset from start of height mesh data		long waterMaskLength;				// Total length of ?2 data		long unknown23;				// No idea		long unknown3_Offset;				// Offset from start of height mesh data		long  unknown3_Length;				// Total length of ?3 data		long unknown24;				// No idea		long unknown25;				// Usually zeros		long unknown26;				// Usually zeros		long unknown27;				// Usually zeros		windTAG windEffects;		// Wind effects, usually FFFF		long unknown28;				// Usually zeros		long unknown29;				// Usually zeros		long unknown30;				// Usually zeros		long unknown31;				// Usually zeros		long unknown32;				// Usually zeros		stliTAG captions;			// Captions (stli tag reference)		sounTAG narrationSound;		// Narration voice (soun tag reference)		long unknown33[191];		// Spacer zeros?	};								// 1024 bytes		struct gridData	{		short height;				// 16 bit height map, signed integer		unsigned char slopeA;				// 16 bit unsigned integer [1]		unsigned char slopeB;		unsigned char water;					// Effects of water (reflections, etc)?		unsigned char passability;			// Two 4-bit passability flags [2]		char unknown1;				// Possibly unused, usually FF		char unknown2;				// Possibly unused, usually FF	};								// 8 bytes	struct itemTypeData	{		short itemType;								// The type of item listed [1]		short flags1;								// [2]		long itemID;								// The ID tag of the item type		short teamNumber;							// Which team the item belongs to [3]		char unknown1[16];							// Usually zeros		short itemMax1;								// Number of itemType present on level [4]		short itemMax2;                             // Max number of itemType allowed on													// level (multiplayer) [5]		short itemRef;								// Reference number used in following													// section.	}; // 32 bytes	struct itemListData	{		short unknown1;								// No idea. Often it is all 0's		short initialItem;							// Flag whether level starts with item													// present [1]		short itemType; 							// The type of item listed [2]		short itemRef;								// Reference number from itemTypeData		short itemID1;								// Unique ID number for this instance													// of the item		short unknown2;								// No idea.		long itemPosition[3];						// (X,Y,Z) position on the mesh [3]		char unknown3;								// No idea. Usually all 0's		char unknown4;								// No idea. Usually all 0's		char unknown5;								// No idea. Usually all 0's		char unknown6;								// No idea. Usually all 0's		char unknown7;								// No idea. Usually all 0's		char unknown8;								// No idea. Usually all 0's		char unknown9;								// No idea. Usually all 0's		char unknown10;								// No idea. Usually all 0's		short facing;								// Direction the item is facing [4]		char unknown11[26];							// No idea. Usually all 0's.		short itemID2;								// Another unique number for each item		short itemID3;								// Yet another unique number [5]	};										// 64 bytes